			if diff := cmp.Diff(tc.want, agreementNativeHeadingReading(tc.body)); diff != "" {
				t.Fatalf("caught: complete native heading source (-want +got):\n%s", diff)
			}
			_, actual := agreementIsolatedPage(t, agreementCase{Body: tc.body})
			var names []string
			for name := range tc.want.Names {
				names = append(names, name)
			}
			slices.Sort(names)
			probe := actual
			probe.Headings = names
			for _, f := range agreementFragmentFailures(t, []agreementCase{{Body: tc.body}}, []agreementHTML{probe})[0] {
				if f.Property == "P4" {
					t.Fatalf("caught: native heading full check name lacks public acceptance %s", agreementSignature(&f))
				}
			}
