func TestAgreementNativeHeadingSourceDrift(t *testing.T) {
	t.Parallel()
	c := agreementCase{Body: "> [!note] one\n> [!note] two\n> [!note] three\n## A-2\n## A\n## A\n| a | b |\n|---|---|\n| [[A]] | ^a |\nA\n===\n ^a\n      > [!note] title\n[[#A]]%%[[A]]%%[[A\\|alias]]## <em>A</em>\n## A\n\n[^u]: [[C]]\n\n%%hidden%%\n\n```\n[[D]]\n```\n"}
	_, actual := agreementIsolatedPage(t, c)
	budget := agreementNativeHeadingBudget(c.Body, &actual)
	f := agreementFailure{Property: "P4", Identity: "literal-heading-id", Direction: "page-only", Fragment: "a-3", Multiplicity: 1, PagePresent: true}
	if kind, authority, wrong := agreementNativeHeadingDifference(c, &f, &actual, &budget); kind != "debt" || authority != "#1011 stage 8" || wrong != "judge" {
		t.Fatal("caught: native heading source drift control is unowned")
	}
	source := &budget.Source
	if len(source.Native.Definitions) != 1 || len(source.Native.Code) != 1 || len(source.Native.Comments) != 2 || len(source.Check.Fields) != 6 || len(source.Check.Code) != 1 || len(source.Check.Comments) != 2 || len(source.Plain.Headings) != 5 || len(source.Plain.Fields) != 1 || len(source.Page.Headings) != 4 || len(source.Parsed) != 5 || len(source.Generous) != 5 {
		t.Fatal("caught: native heading drift baseline lacks complete declared collections")
	}
	other := c
	other.Body = strings.Replace(c.Body, "hidden", "shadow", 1)
	if !cmp.Equal(agreementNativeHeadingReading(other.Body), budget.Source) {
		t.Fatal("caught: body binding control changed declared heading facts")
	}
	if kind, _, _ := agreementNativeHeadingDifference(other, &f, &actual, &budget); kind != "" {
		t.Fatal("caught: native heading borrowed different bytes with identical declared facts")
	}
	for _, tc := range []struct {
		name   string
		change func(*agreementNativeHeadingSource)
	}{
		{"plain eligibility", func(s *agreementNativeHeadingSource) { s.Plain.Eligible = false }},
		{"page eligibility", func(s *agreementNativeHeadingSource) { s.Page.Eligible = false }},
		{"plain names", func(s *agreementNativeHeadingSource) { s.Plain.Checks[0] = "unowned" }},
		{"page names", func(s *agreementNativeHeadingSource) { s.Page.Bases[0] = "unowned" }},
		{"plain heading span", func(s *agreementNativeHeadingSource) { s.Plain.Headings[0].Stop++ }},
		{"page heading span", func(s *agreementNativeHeadingSource) { s.Page.Headings[0].Stop++ }},
		{"plain field roles", func(s *agreementNativeHeadingSource) { s.Plain.Fields[0].Role = "unowned" }},
		{"native code kind", func(s *agreementNativeHeadingSource) { s.Native.Code[0].Kind = "unowned" }},
		{"native code span", func(s *agreementNativeHeadingSource) { s.Native.Code[0].Span.Stop++ }},
		{"native definition", func(s *agreementNativeHeadingSource) { s.Native.Definitions[0].Label = "unowned" }},
		{"native node", func(s *agreementNativeHeadingSource) { s.Native.Definitions[0].Nodes[0].Depth++ }},
		{"native comment", func(s *agreementNativeHeadingSource) { s.Native.Comments[0].Stop++ }},
		{"whole check targets", func(s *agreementNativeHeadingSource) { s.Check.Targets = append(s.Check.Targets, "unowned") }},
		{"plain code", func(s *agreementNativeHeadingSource) { s.Check.Code = nil }},
		{"plain comments", func(s *agreementNativeHeadingSource) { s.Check.Comments = nil }},
		{"field order", func(s *agreementNativeHeadingSource) {
			s.Check.Fields[0], s.Check.Fields[1] = s.Check.Fields[1], s.Check.Fields[0]
		}},
		{"field bytes", func(s *agreementNativeHeadingSource) { s.Check.Fields[0].Word = "[[unowned]]" }},
		{"field span", func(s *agreementNativeHeadingSource) { s.Check.Fields[0].Span.Stop++ }},
		{"field names", func(s *agreementNativeHeadingSource) { s.Check.Fields[0].Targets = []string{"unowned"} }},
		{"field owner", func(s *agreementNativeHeadingSource) { s.Check.Fields[0].DefinitionOwner = 0 }},
		{"surface", func(s *agreementNativeHeadingSource) { s.Surface += "unowned" }},
		{"parsed declaration order", func(s *agreementNativeHeadingSource) { s.Parsed[0], s.Parsed[1] = s.Parsed[1], s.Parsed[0] }},
		{"parsed span", func(s *agreementNativeHeadingSource) { s.Parsed[0].Span.Stop++ }},
		{"parsed bytes", func(s *agreementNativeHeadingSource) { s.Parsed[0].Raw = "unowned" }},
		{"parsed words", func(s *agreementNativeHeadingSource) { s.Parsed[0].Words = "unowned" }},
		{"parsed name", func(s *agreementNativeHeadingSource) { s.Parsed[0].Name = "unowned" }},
		{"parsed level", func(s *agreementNativeHeadingSource) { s.Parsed[0].Level++ }},
		{"generous declaration order", func(s *agreementNativeHeadingSource) { s.Generous[0], s.Generous[1] = s.Generous[1], s.Generous[0] }},
		{"generous span", func(s *agreementNativeHeadingSource) { s.Generous[0].Span.Stop++ }},
		{"generous bytes", func(s *agreementNativeHeadingSource) { s.Generous[0].Raw = "unowned" }},
		{"generous words", func(s *agreementNativeHeadingSource) { s.Generous[0].Words = "unowned" }},
		{"generous name", func(s *agreementNativeHeadingSource) { s.Generous[0].Name = "unowned" }},
		{"generous level", func(s *agreementNativeHeadingSource) { s.Generous[0].Level++ }},
		{"missing check name", func(s *agreementNativeHeadingSource) { delete(s.Names, "a") }},
		{"extra check name", func(s *agreementNativeHeadingSource) { s.Names["unowned"] = true }},
		{"allocated names", func(s *agreementNativeHeadingSource) { s.Allocated[0] = "unowned" }},
		{"allocated order", func(s *agreementNativeHeadingSource) { s.Allocated[0], s.Allocated[1] = s.Allocated[1], s.Allocated[0] }},
		{"selected extra", func(s *agreementNativeHeadingSource) { s.Selected["unowned"] = true }},
		{"selected member", func(s *agreementNativeHeadingSource) { delete(s.Selected, "a-4") }},
	} {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			changed := agreementNativeHeadingPayload{Body: c.Body, Source: agreementNativeHeadingReading(c.Body)}
			tc.change(&changed.Source)
			if kind, _, _ := agreementNativeHeadingDifference(c, &f, &actual, &changed); kind != "" {
				t.Fatal("caught: native heading borrowed changed complete source")
			}
		})
	}
}
